INSERT INTO tbl_offer_letters (job_appliactions_id, job_circular_id, offer_subject, offer_body, salary_offered, joining_date, additional_terms, status, created_by, created_at) VALUES (258, 17, 'Job Offer: Web Developer (PHP, Laravel, CodeIgniter, WordPress) at TIC Limited', '<p>Dear <strong>{CANDIDATE_NAME}</strong>,</p><p>We are pleased to offer you the position of <strong>{JOB_TITLE}</strong> at <strong>{COMPANY_NAME}</strong>.</p><p><strong>Position Details:</strong></p><ul><li><strong>Position:</strong> {JOB_TITLE}</li><li><strong>Designation:</strong> {DESIGNATION}</li><li><strong>Salary:</strong> {SALARY}</li><li><strong>Joining Date:</strong> {JOINING_DATE}</li><li><strong>Employment Type:</strong> {EMPLOYMENT_TYPE}</li></ul><p>{ADDITIONAL_TERMS}</p><p>We look forward to having you on our team. Please confirm your acceptance by replying to this email.</p><p>Best Regards,<br>The <strong>{SITE_NAME}</strong> Team</p>', 22000, '2026-06-01', 'nothing', 'draft', 1, NOW());
